begin;
alter table public.appointments add column if not exists terms_accepted_at timestamptz;
alter table public.appointments add column if not exists booking_notified_at timestamptz;
create table if not exists public.beautyflow_rate_limits(key text primary key,attempts integer not null default 0,expires_at timestamptz not null);
alter table public.beautyflow_rate_limits enable row level security;
create or replace function public.beautyflow_allow_rate_limit(p_key text,p_limit integer,p_window_seconds integer) returns boolean language plpgsql security definer set search_path=public as $$ declare used integer; begin if p_limit<1 or p_window_seconds<1 then return false;end if;insert into public.beautyflow_rate_limits(key,attempts,expires_at) values(p_key,1,now()+make_interval(secs=>p_window_seconds)) on conflict(key) do update set attempts=case when beautyflow_rate_limits.expires_at<=now() then 1 else beautyflow_rate_limits.attempts+1 end,expires_at=case when beautyflow_rate_limits.expires_at<=now() then now()+make_interval(secs=>p_window_seconds) else beautyflow_rate_limits.expires_at end returning attempts into used;return used<=p_limit;end $$;
revoke all on function public.beautyflow_allow_rate_limit(text,integer,integer) from public,anon,authenticated;grant execute on function public.beautyflow_allow_rate_limit(text,integer,integer) to service_role;
create or replace function public.beautyflow_create_appointment_atomic(p_salon uuid,p_service uuid,p_staff uuid,p_date date,p_start time,p_end time,p_customer_name text,p_customer_phone text,p_customer_phone_normalized text,p_customer_email text,p_note text,p_terms_accepted_at timestamptz) returns uuid language plpgsql security definer set search_path=public as $$ declare new_id uuid;begin perform pg_advisory_xact_lock(hashtextextended(p_staff::text||p_date::text,0));if not exists(select 1 from public.salons where id=p_salon and active=true) then raise exception 'Салонът не е активен.';end if;if not exists(select 1 from public.services where id=p_service and salon_id=p_salon and active=true) then raise exception 'Услугата не е активна.';end if;if not exists(select 1 from public.staff where id=p_staff and salon_id=p_salon and active=true and deleted_at is null) then raise exception 'Специалистът не е активен.';end if;if exists(select 1 from public.appointments where salon_id=p_salon and appointment_date=p_date and status<>'cancelled' and (staff_id=p_staff or staff_id is null) and start_time<p_end and end_time>p_start) then raise exception 'Часът вече е зает.';end if;insert into public.appointments(salon_id,service_id,staff_id,appointment_date,start_time,end_time,customer_name,customer_phone,customer_phone_normalized,customer_email,note,status,terms_accepted_at) values(p_salon,p_service,p_staff,p_date,p_start,p_end,p_customer_name,p_customer_phone,p_customer_phone_normalized,p_customer_email,p_note,'confirmed',p_terms_accepted_at) returning id into new_id;return new_id;end $$;
revoke all on function public.beautyflow_create_appointment_atomic(uuid,uuid,uuid,date,time,time,text,text,text,text,text,timestamptz) from public,anon,authenticated;grant execute on function public.beautyflow_create_appointment_atomic(uuid,uuid,uuid,date,time,time,text,text,text,text,text,timestamptz) to service_role;
create or replace function public.beautyflow_claim_booking_notification(p_appointment uuid) returns boolean language plpgsql security definer set search_path=public as $$ declare changed integer;begin update public.appointments set booking_notified_at=now() where id=p_appointment and booking_notified_at is null;get diagnostics changed=row_count;return changed=1;end $$;
revoke all on function public.beautyflow_claim_booking_notification(uuid) from public,anon,authenticated;grant execute on function public.beautyflow_claim_booking_notification(uuid) to service_role;
commit;